// is include-set NEUTRAL for every TU that takes both headers (the same
// nine enumerators, one file earlier in the same closure); hero.cpp is
// the only consumer that gains them, and its rows were re-measured
// unchanged.
enum TWallTargetId {
    WALL_TARGET_0 = 0,
    WALL_TARGET_1 = 1,
    WALL_TARGET_2 = 2,
    WALL_TARGET_3 = 3,
    WALL_TARGET_4 = 4,
    WALL_TARGET_5 = 5,
    WALL_TARGET_6 = 6,
    WALL_TARGET_7 = 7,
    WALL_TARGET_COUNT = 8
};

